mapper.select:
SELECT BASE_SUBJECT_NATURE
FROM BOK_SUBJECT_NATURE_GROUP
WHERE GROUP_ID = #{groupId}
 AND ACCT_STANDARD_ID = #{acctStandardId}

SELECT TEMP.*, bbd.BOOKSET_DATE AS booksetDate FROM ( SELECT bc.BOOKSET_ID AS booksetId, bc.BOK_DETAIL_ID as bokDetailId, bdi.BUSI_ID as busiId, bdi.BUSI_DETAIL_TYPE as busiDetailType, bc.TABLE_ID AS tableId, bc.SUBJECT_NO AS subjectNo, bdi.INV_AIM as invAim, bc.O_CCY AS oCcy, bc.B_CCY AS bCcy, bc.BAL_FLAG_HAPPEN_DATE as balFlagHappenDate, bc.O_AMT_HAPPEN_DATE AS balance, bc.B_AMT_HAPPEN_DATE AS bAmt, bc.NUM_AMT_HAPPEN_DATE AS num, ROW_NUMBER() OVER(PARTITION BY bc.BOOKSET_ID, bc.BOK_DETAIL_ID, bc.BASE_SUBJECT_NATURE, bc.BRANCH, bc.O_CCY ORDER BY bc.BOOK_ORDER DESC ) AS rn, bc.HAPPEN_DATE AS happenDate, bc.BASE_SUBJECT_NATURE as baseSubjectNature,
bc.DETAIL_SUBJECT_NO AS detailSubjectNo, bs.BAL_FLAG ,bc.MDATE mdate FROM BOK_BOOKDETAIL_CURRENT bc LEFT JOIN BOK_DETAIL_ID bdi ON bdi.BOOKSET_ID = bc.BOOKSET_ID AND bdi.BOK_DETAIL_ID = bc.BOK_DETAIL_ID LEFT JOIN SYS_BATCH_TASK bt on bt.task_id = bc.task_id LEFT JOIN BOK_BOOKSET bb ON bc.BOOKSET_ID = bb.BOOKSET_ID /**账套表**/ LEFT JOIN BOK_SUBJECT bs ON bs.BOOKSET_ID = bb.BOOKSET_ID_TMPL AND bs.SUBJECT_NO = bc.SUBJECT_NO WHERE 1=1
AND bc.BOOKSET_ID = #{booksetId}
AND bdi.BUSI_ID = #{busiId}
AND bc.HAPPEN_DATE <= #{happenDate}
AND ( bc.HAPPEN_DATE < #{happenDate} OR ( bc.HAPPEN_DATE = #{happenDate} AND nvl(bt.task_pri,bc.TASK_PRI) < #{taskPri} ) )
AND bc.BOOK_DATE <= #{bookDate} AND (bc.OFFSET_DATE < #{bookDate} OR bc.OFFSET_DATE IS NULL)
AND bdi.INV_AIM IN
#{invAim}
AND bc.BASE_SUBJECT_NATURE IN
#{baseSubjectNature}
AND bc.TABLE_ID = #{tableId}
AND bs.SUBJECT_TYPE IN
#{subjectType}
AND bc.BOK_DETAIL_ID in
#{item}
AND bc.BOK_DETAIL_ID = #{bokDetailId}
AND bc.BOOK_ORDER <= #{bookOrder}
AND ( bc.ONWAY_DATE <= #{onwayDate} OR bc.ONWAY_DATE IS NULL )
AND bc.BRANCH = #{branch}
) TEMP INNER JOIN BOK_BOOKSET_DATE bbd ON bbd.BOOKSET_ID = TEMP.booksetId WHERE TEMP.rn=1
